  "milestones": [
    {
      "name": "find composter",
      "description": "The agent must navigate to and find the composter block located near the farm area. The composter is at approximately 2 blocks east and 2 blocks south of spawn, on the edge of the crop field.",
      "rules": [
        {
          "type": "position_inside_box",
          "description": "Agent must be within 3 blocks of the composter (located at ~2, ~1, ~2 relative to spawn)",
          "parameters": {
            "x_min": "~-1",
            "x_max": "~5",
            "y_min": "~-1",
            "y_max": "~3",
            "z_min": "~-1",
            "z_max": "~5"
